// Data Hazard: Read After Write (RAW)
// Instruction dependency requires sequencing

typedef struct PipelinedInst {
    int opcode;
    int source_reg; // Value to be read
    int dest_reg;   // Value to be written
} PipelinedInst;

// I1: ADD R1, R2, R3 (R1 is destination)
PipelinedInst I1 = { 0x20, R2, R1 };

// I2: SUB R4, R1, R5 (R1 is source)
PipelinedInst I2 = { 0x22, R1, R4 };

// Hazard Condition:
// (I1.dest_reg == I2.source_reg)

// Timing Conflict:
// I2 (ID Stage) needs R1 value (Cycle N+1)
// I1 (EX Stage) produces R1 value (Cycle N+2)

// Solution: Forwarding/Bypassing
// Data moves from I1's EX/MEM Register to I2's EX Stage input.
